negativeExample:
class Example {
    String replaceAllOccurrences(String text) {
        // Not a single character literal for the replacement, should not match
        return text.replace("foo", "bar");
    }
    String replaceDynamic(String text, String oldChar, String newChar) {
        // Arguments are not string literals, should not match
        return text.replace(oldChar, newChar);
    }
    String replaceRegex(String text) {
        // This method treats arguments as literal strings, so '.*' is not a regex
        // The rule is still semantically correct, but it's not the intent of the negative example for a regex case.
        // A true regex case would be replaceAll(), which is not matched.
        return text.replace(".*", "replacement");
    }
}

